package net.valor.world.level.levelgen.structure;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.structure.Structure;
import net.minecraft.world.level.levelgen.structure.StructureSet;
import net.valor.Valor;

/**
 * Keys of Valor's structures and structure sets. Counterpart to vanilla's {@code BuiltinStructures} and
 * {@code BuiltinStructureSets}. The contents are data, generated by the worldgen datagen providers.
 */
public final class ValorStructures {

	/** A collapsed forest gate. The most common ruin; likes small clearings. */
	public static final ResourceKey<Structure> FALLEN_GATE = structure("fallen_gate");
	/** Low walls half sunk into the ground, the largest dig site. Likes hollows and flat ground. */
	public static final ResourceKey<Structure> SUNKEN_RUIN = structure("sunken_ruin");
	/** An old watchtower. The rarest ruin, a small landmark. */
	public static final ResourceKey<Structure> TOWER_RUIN = structure("tower_ruin");

	/** All Whispering Woods ruins share one placement: weighted choice, spaced apart. */
	public static final ResourceKey<StructureSet> WHISPERING_WOODS_RUINS = set("whispering_woods_ruins");

	private ValorStructures() {}

	private static ResourceKey<Structure> structure(String name) {
		return ResourceKey.create(Registries.STRUCTURE, Valor.id(name));
	}

	private static ResourceKey<StructureSet> set(String name) {
		return ResourceKey.create(Registries.STRUCTURE_SET, Valor.id(name));
	}
}
